class Product:
    def __init__(self, price):
        self.price = price

    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, value):
        if value < 0:
            raise ValueError("negative")
        self._price = round(value, 2)

p = Product(9.999)
try:
    p.price = -1
except ValueError:
    pass
print(p.price)

