class Cleaner:
    def process(self, x):
        return x

class Upper(Cleaner):
    def process(self, x):
        return x.upper()

class Strip(Cleaner):
    def process(self, x):
        return x.strip()

value = "  ok "
for step in [Strip(), Upper(), Cleaner()]:
    value = step.process(value)
print(repr(value))

