class Sku:
    def __init__(self, code):
        self.code = code

class Sku2(Sku):
    def __eq__(self, other):
        return isinstance(other, Sku2) and self.code == other.code

print(Sku("A1") == Sku("A1"), Sku2("A1") == Sku2("A1"), Sku2("A1") is Sku2("A1"))

